const BY_BEAT = []
for (const h of HARMONY) for (let b = h[0]; b < h[0] + h[1]; b++) BY_BEAT[b] = h
const chordAt = x => BY_BEAT[floor(x)] ?? null
const padOn = x => chordAt(x) && ['themeB', 'bridge', 'break', 'final', 'intro'].includes(role(x)) && x < END - 2 // pads play here
const SCALE = [5, 7, 8, 10, 0, 1, 3] // F минор, pitch classes from C

// ---- the stage: sections, key changes, the kick and the sidechain -----------------------------------------------------------
const SEC = 60 / 125 // seconds per beat
const sectionEnd = x => ROLE.find(r => r[0] > x)?.[0] ?? END
const KEY_UP = [[192,2]] // [start, semitones up]
const trAt = x => { let t = 0; for (const [s, k] of KEY_UP) if (s <= x) t = k; return t }
const KICK_N = 29 // MIDI: the kick's body sits on the tonic (F1, 43.6535 Hz)
// the kick by energy: 16 steps a bar (x = hit); none in the breakdown (bridge), none in the last bar of a build-up
const KICK = {"1":"x---x---x---x---","2":"x---x---x---x---","3":"x---x---x---x---"}
const kickAt = x => {
  if (x < 0 || x >= END) return null
  const [s, r, e] = sectionOf(x), t = x - s, L = sectionEnd(x) - s
  if (r === 'build') return t < L - 4 ? { τ: mod(t, 1), vel: 0.7 + (0.3 * t) / L } : null
  if (r === 'outro' && t >= L - 4) return { τ: t - L + 4, vel: 0.9 }
  if (r === 'bridge') return null
  for (let b = floor(x / 4) * 4; b >= floor(x / 4) * 4 - 4 && b >= s; b -= 4) {
    const pat = KICK[energy(b)]
    if (pat) for (let i = 15; i >= 0; i--) if (pat[i] === 'x' && b + i / 4 <= x) return { τ: x - b - i / 4, vel: 1 }
  }
  return null
}
// the sidechain: every part dips under the kick and comes back in 0.2 s — deepest in a drop
const pumpAt = x => { const k = kickAt(x); return k ? duck(k.τ * SEC, 0.75 * (energy(x) >= 3 ? 1 : 0.6), 0.2) : 1 }

// ---- melodies: [beat, n from C4, length] — draw them in the piano roll ------------------------------
